import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    t = input_data[1]
    m = int(input_data[2])

    words_raw = input_data[3:]

    transformed_words = {}

    for w in words_raw:
        w_lower = w.lower()
        w_reversed = w_lower[::-1]
        if w_reversed not in transformed_words:
            transformed_words[w_reversed] = []
        transformed_words[w_reversed].append(w)

    dp = [None] * (n + 1)
    dp[0] = []

    for i in range(n):
        if dp[i] is None:
            continue

        j = i
        while j < n:
            segment = t[i:j+1]
            if segment in transformed_words:
                if dp[j+1] is None:
                    dp[j+1] = dp[i] + [transformed_words[segment][0]]
                else:
                    pass

            j += 1
            if j - i + 1 > 1000:
                break

    if dp[n] is None:
        return

    print(" ".join(dp[n]))

if __name__ == "__main__":
    solve()
